// Builds the generated parts of the skill from src/: the engine for scripts/build.mjs (scripts/engine.mjs: read, check,
// the facilitator's script, a game and its debrief, and visual-explainer's reader for the drawings) and the drill page with
// its code and visual-explainer's drawing inside (assets/drill.html). Run: npm run assets. Never edit the generated files.
import { build } from 'esbuild'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { vendor } from '../../../kit/tools/vendor.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const root = resolve(here, '..')
const repo = resolve(here, '../../..') // the dna repository
const skill = join(repo, 'skills/incident-drill')
const chalk = JSON.parse(readFileSync(join(repo, 'node_modules/@ruinosus/visual-explainer/package.json'), 'utf8')).version
const banner = `// GENERATED by tools/assets.mjs (visual-explainer ${chalk}). Do not edit.`

// visual-explainer's contract alone (the recipe reader), not its renderer
const contract = join(repo, 'node_modules/@ruinosus/visual-explainer/scripts/contract.mjs')
const engine = await build({
  entryPoints: [join(root, 'src/engine.ts')],
  bundle: true, format: 'esm', platform: 'node', target: 'node18', minify: true, write: false, logLevel: 'warning',
  nodePaths: [join(repo, 'node_modules')],
  alias: { 'chalk-contract': contract, '@kit': join(repo, 'node_modules/@ruinosus/visual-explainer/kit') },
  banner: { js: "import { createRequire } from 'node:module'; const require = createRequire(import.meta.url);" },
})
writeFileSync(join(skill, 'scripts/engine.mjs'), `${banner}\n${engine.outputFiles[0].text}`)

// the game alone (src/play.ts: pure, no Node), for the dna mod's /drill pane: hooks/drill/play.js
const play = await build({
  entryPoints: [join(root, 'src/play.ts')],
  bundle: true, format: 'esm', platform: 'neutral', target: 'es2022', write: false, logLevel: 'warning',
  alias: { '@kit': join(repo, 'node_modules/@ruinosus/visual-explainer/kit') },
})
if (/\bfrom ['"]node:|\brequire\(/.test(play.outputFiles[0].text)) throw new Error('src/play.ts reaches Node: the mod cannot load it')
writeFileSync(join(repo, 'hooks/drill/play.js'), `// GENERATED by dev/incident-drill/tools/assets.mjs from src/play.ts, for the mod's /drill. Do not edit.\n${play.outputFiles[0].text}`)

const css = readFileSync(join(root, 'src/page/drill.css'), 'utf8')
const page = await build({
  entryPoints: [join(root, 'src/page/drill.ts')],
  bundle: true, format: 'iife', target: 'es2020', minify: true, write: false, logLevel: 'warning',
  nodePaths: [join(repo, 'node_modules')],
})
const script = page.outputFiles[0].text
if (/<\/script/i.test(script)) throw new Error('The page script contains "</script": it would end the page early.')
const html = readFileSync(join(root, 'src/page/template.html'), 'utf8').replace(/\{\{(VERSION|CSS|JS)\}\}/g, (_, k) => ({ VERSION: `visual-explainer ${chalk}`, CSS: css, JS: script })[k])
if (!html.includes('{{DRILL}}')) throw new Error('The template lost its {{DRILL}} slot.')
writeFileSync(join(skill, 'assets/drill.html'), html)
writeFileSync(join(skill, 'assets/VERSION'), `visual-explainer ${chalk}\n`)
// DNA 2.1.0: the kit's OKF reader, for writing a drill from an OKF bundle (SKILL.md, «From an OKF bundle»)
vendor(join(skill, 'scripts'), ['okf-read.mjs'])
console.log(`✓ assets: engine.mjs ${(engine.outputFiles[0].text.length / 1024).toFixed(0)} KB, hooks/drill/play.js, drill.html ${(html.length / 1024).toFixed(0)} KB (visual-explainer ${chalk})`)
